 void question(String title,String text,String url){if(retired)return;final String raw=Json.write(Json.map("id","project-"+System.currentTimeMillis(),"title",title,"question",text,"url",url));disk.execute(new Runnable(){public void run(){try{Payloads.writeSmall(new File(home,".trough/project-question.json"),raw);}catch(Exception e){android.util.Log.e("ProjectWorker","Question persistence",e);}}});}
 void connect(){if(blocked&&thread.length()==0){status("recovery_required",error);return;}try{agent=new CodexAgent(exe,cwd,env,thread,model,effort,"danger-full-access",this);status("connecting",blocked?error:"");}catch(Exception e){blocked=true;status("connection_failed",e.toString());}}
 void status(String value,String failure){if(retired)return;state=value;error=failure==null?"":failure;lastActivity=System.currentTimeMillis();final String raw=Json.write(Json.map("producer","halfsword_direct_worker","lifecycle_version",2,"handoff_version",1,"process_restore_version",1,"state",state,"ready",ready,"busy",busy,"blocked",blocked,"thread_id",thread,"model",model,"effort",effort,"time_ms",lastActivity,"completed_units",completed,"pending_sends",pending.size(),"error",error));disk.execute(new Runnable(){public void run(){try{Payloads.writeSmall(runtime,raw);}catch(Exception e){android.util.Log.e("ProjectWorker","Runtime persistence",e);}}});}
 void row(String kind,String text){if(retired)return;if(text==null||text.length()==0)return;if(text.length()>6000)text=text.substring(0,6000)+"\n[Truncated for bounded view]";rows.add(Json.map("id","direct-"+System.currentTimeMillis()+"-"+(serial++),"kind",kind,"text",text,"time_ms",System.currentTimeMillis()));while(rows.size()>12)rows.remove(0);saveRows();}
 static int utf8Size(String s){try{return s.getBytes("UTF-8").length;}catch(Exception e){return s.length()*3;}}
 void saveRows(){if(retired)return;Map<String,Object> data=Json.map("schema_version",1,"project","half-sword","producer","halfsword_direct_worker","worker_thread_id",thread,"entries",new ArrayList<Map<String,Object>>(rows));String raw=Json.write(data);while(utf8Size(raw)>28000&&rows.size()>1){rows.remove(0);data.put("entries",new ArrayList<Map<String,Object>>(rows));raw=Json.write(data);}final String encoded=raw;disk.execute(new Runnable(){public void run(){try{Payloads.writeSmall(output,encoded);}catch(Exception e){android.util.Log.e("ProjectWorker","Transcript persistence",e);}}});}
 void flush(){if(retired)return;streamScheduled=false;if(stream.length()==0)return;if(liveId.length()==0){liveId="direct-stream-"+System.currentTimeMillis()+"-"+(serial++);rows.add(Json.map("id",liveId,"kind","assistant","text","","time_ms",System.currentTimeMillis()));}for(Map<String,Object> r:rows)if(liveId.equals(r.get("id")))r.put("text",stream.length()>6000?stream.substring(stream.length()-6000):stream.toString());while(rows.size()>12)rows.remove(0);saveRows();}
